fn draw_native_2d_authoring_gizmos(
    lines: &mut DebugLines,
    scene: &AuthoringScene,
    pick_info: &[EntityPickInfo],
) {
    let sprite_type = ComponentTypeId::new(engine::scene_bridge::SPRITE_RENDERER_2D_COMPONENT);
    let collider_type = ComponentTypeId::new(engine::scene_bridge::COLLIDER_2D_COMPONENT);
    let controller_type =
        ComponentTypeId::new(engine::scene_bridge::CHARACTER_CONTROLLER_2D_COMPONENT);
    let sprite_color = Vec3::new(0.95, 0.35, 0.95);
    let collider_color = Vec3::new(0.1, 0.9, 0.95);
    let platform_color = Vec3::new(1.0, 0.7, 0.15);
    let controller_color = Vec3::new(0.3, 1.0, 0.35);

    for info in pick_info {
        let Some(entity) = scene.entity(&info.id) else {
            continue;
        };
        if entity.components.contains_key(&sprite_type) {
            let marker = 0.12_f32.max(info.half.x.min(info.half.y) * 0.2);
            lines.line(
                info.center - Vec3::X * marker,
                info.center + Vec3::X * marker,
                sprite_color,
            );
            lines.line(
                info.center - Vec3::Y * marker,
                info.center + Vec3::Y * marker,
                sprite_color,
            );
            lines.aabb(
                info.center,
                Vec3::new(info.half.x, info.half.y, 0.01),
                sprite_color,
            );
        }

        if let Some(Value::Object(fields)) = entity.components.get(&collider_type) {
            let one_way = matches!(fields.get("one_way"), Some(Value::Bool(true)));
            let color = if one_way { platform_color } else { collider_color };
            match fields.get("shape") {
                Some(Value::String(shape)) if shape == "circle" => {
                    let radius = obj_f64_or(fields, "radius", 0.5).max(0.001) as f32;
                    draw_rotation_ring(lines, info.center, [0.0, 0.0, 1.0], color, radius);
                }
                Some(Value::String(shape)) if shape == "capsule" => {
                    let radius = obj_f64_or(fields, "radius", 0.5).max(0.001) as f32;
                    let half_height =
                        obj_f64_or(fields, "half_height", 0.5).max(0.0) as f32;
                    let top = info.center + Vec3::Y * half_height;
                    let bottom = info.center - Vec3::Y * half_height;
                    draw_rotation_ring(lines, top, [0.0, 0.0, 1.0], color, radius);
                    draw_rotation_ring(lines, bottom, [0.0, 0.0, 1.0], color, radius);
                    lines.line(top - Vec3::X * radius, bottom - Vec3::X * radius, color);
                    lines.line(top + Vec3::X * radius, bottom + Vec3::X * radius, color);
                }
                Some(Value::String(shape)) if shape == "polygon" => {
                    let points = fields
                        .get("points")
                        .and_then(|value| match value {
                            Value::Array(points) => Some(points),
                            _ => None,
                        })
                        .map(|points| {
                            points
                                .iter()
                                .filter_map(|point| match point {
                                    Value::Object(point) => Some(info.world.transform_point3(
                                        Vec3::new(
                                            obj_f64(point, "x") as f32,
                                            obj_f64(point, "y") as f32,
                                            0.0,
                                        ),
                                    )),
                                    _ => None,
                                })
                                .collect::<Vec<_>>()
                        })
                        .unwrap_or_default();
                    if points.len() >= 2 {
                        for index in 0..points.len() {
                            lines.line(points[index], points[(index + 1) % points.len()], color);
                        }
                    }
                }
                _ => {
                    let half_x = obj_f64_or(fields, "half_extent_x", 0.5).max(0.001) as f32;
                    let half_y = obj_f64_or(fields, "half_extent_y", 0.5).max(0.001) as f32;
                    let corners = [
                        info.world.transform_point3(Vec3::new(-half_x, -half_y, 0.0)),
                        info.world.transform_point3(Vec3::new(half_x, -half_y, 0.0)),
                        info.world.transform_point3(Vec3::new(half_x, half_y, 0.0)),
                        info.world.transform_point3(Vec3::new(-half_x, half_y, 0.0)),
                    ];
                    for index in 0..4 {
                        lines.line(corners[index], corners[(index + 1) % 4], color);
                    }
                }
            }
            if one_way {
                let extent = obj_f64_or(fields, "half_extent_x", 0.5).max(0.25) as f32;
                let top = info.center
                    + Vec3::Y * obj_f64_or(fields, "half_extent_y", 0.5) as f32;
                lines.line(top - Vec3::X * extent, top + Vec3::X * extent, platform_color);
            }
        }

        if let Some(Value::Object(fields)) = entity.components.get(&controller_type) {
            let half_x = obj_f64_or(fields, "half_extent_x", 0.45).max(0.001) as f32;
            let half_y = obj_f64_or(fields, "half_extent_y", 0.9).max(0.001) as f32;
            lines.aabb(
                info.center,
                Vec3::new(half_x, half_y, 0.01),
                controller_color,
            );
        }
    }
}

